import { __ } from '@wordpress/i18n';
import { PanelBody, ToggleControl } from "@wordpress/components";
import { BControlPro } from '../../../../../../bpl-tools/ProControls';

const VideoGeneral = ({ attributes, setAttributes, updateObject, premiumProps }) => {
    const { videoConf } = attributes;
    const { controls, isPopup, icon, repeat, isAutoPlay, muted, resetOnEnd, autoHideControl } = videoConf;
    const { restart, rewind, play, progress, duration, pip, volume, mute, airplay, settings, download, fullscreen } = controls;

    return <>
        <PanelBody className='bPlPanelBody' title={__('Video', 'slider')} initialOpen={false}>
            <ToggleControl className='mt10' label={__('Popup enable', 'slider')} checked={isPopup} onChange={val => updateObject('videoConf', 'isPopup', val)} />

            {isPopup && <ToggleControl className='mt10' label={__('Icon', 'slider')} checked={icon} onChange={val => updateObject('videoConf', 'icon', val)} />}

            <BControlPro className='mt10' label={__('Repeat', 'slider')} checked={repeat} onChange={val => updateObject('videoConf', 'repeat', val)} Component={ToggleControl} {...premiumProps} />

            {/* <ToggleControl className='mt10' label={__('clickToPlay', 'slider')} checked={clickToPlay} onChange={val => updateObject('videoConf', 'clickToPlay', val)} /> */}

            <BControlPro className='mt10' label={__('Autoplay', 'slider')} checked={isAutoPlay} onChange={val => updateObject('videoConf', 'isAutoPlay', val)} Component={ToggleControl} {...premiumProps} />
            <small>{__('Autoplay might require muting based on the browser.', 'slider')}</small>

            <BControlPro className='mt10' label={__('Muted', 'slider')} checked={muted} onChange={val => updateObject('videoConf', 'muted', val)} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Reset On End', 'slider')} checked={resetOnEnd} onChange={val => updateObject('videoConf', 'resetOnEnd', val)} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Auto Hide Control', 'slider')} checked={autoHideControl} onChange={val => updateObject('videoConf', 'autoHideControl', val)} Component={ToggleControl} {...premiumProps} />
        </PanelBody>

        <PanelBody className='bPlPanelBody' title={__('Controls', 'slider')} initialOpen={false}>

            <ToggleControl label={__('Play Large', 'video-player')} checked={controls['play-large']} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'play-large': val } } })} />

            <ToggleControl className='mt10' label={__('Restart', 'video-player')} checked={restart} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'restart': val } } })} />

            <BControlPro className='mt10' label={__('Rewind', 'video-player')} checked={rewind} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'rewind': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Play', 'video-player')} checked={play} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'play': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Fast Forward', 'video-player')} checked={controls['fast-forward']} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'fast-forward': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Progress', 'video-player')} checked={progress} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'progress': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Current Time', 'video-player')} checked={controls['current-time']} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'current-time': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Duration', 'video-player')} checked={duration} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'duration': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Mute', 'video-player')} checked={mute} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'mute': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Volume', 'video-player')} checked={volume} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'volume': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('PIP', 'video-player')} checked={pip} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'pip': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Airplay', 'video-player')} checked={airplay} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'airplay': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Settings', 'video-player')} checked={settings} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'settings': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Download', 'video-player')} checked={download} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'download': val } } })} Component={ToggleControl} {...premiumProps} />

            <BControlPro className='mt10' label={__('Fullscreen', 'video-player')} checked={fullscreen} onChange={val => setAttributes({ videoConf: { ...videoConf, controls: { ...controls, 'fullscreen': val } } })} Component={ToggleControl} {...premiumProps} />
        </PanelBody>
    </>
}
export default VideoGeneral;